css:
@page {
    size: 40mm 30mm;
    margin: 0;
}

html,
body {
    margin: 0 !important;
    padding: 0 !important;
}

.qr-label {
    width: 40mm;
    height: 30mm;
    text-align: center;
    margin: 0;
    padding-top: 0.7mm;
    box-sizing: border-box;
    overflow: hidden;
}

.qr-label img {
    width: 15mm;
    height: 15mm;
    display: block;
    margin: 0 auto;
}

.item-name {
    margin: 0.2mm 0 0 0;
    padding: 0;
    font-family: Tahoma, Arial, sans-serif;
    font-size: 9px;
    font-weight: bold;
    line-height: 1;
    direction: rtl;
    text-align: center;
}

.item-code {
    margin: 0.15mm 0 0 0;
    padding: 0;
    font-family: Arial, sans-serif;
    font-size: 8px;
    font-weight: bold;
    line-height: 1;
    direction: ltr;
    text-align: center;
}

.item-rate {
    margin: 0.2mm 0 0 0;
    padding: 0;
    font-family: Arial, sans-serif;
    font-size: 8px;
    font-weight: bold;
    line-height: 1;
    direction: ltr;
    text-align: center;
}

@page {
    size: 80mm auto;
    margin: 0;
}

html,
body {
    width: 80mm !important;
    margin: 0 !important;
    padding: 0 !important;
}

.print-format {
    width: 80mm !important;
    max-width: 80mm !important;
    margin: 0 !important;
    padding: 3mm !important;
    box-sizing: border-box !important;
}

.print-format table {
    width: 100% !important;
}

@media print {
    .print-format {
        page-break-after: auto !important;
    }

    tr {
        page-break-inside: avoid !important;
    }
}

{# ---------------------------------------------------------
   Calculate a safe initial page height.

   JavaScript below will measure the exact rendered height
   before printing. This Jinja calculation is the fallback
   for PDF engines that do not execute JavaScript.
---------------------------------------------------------- #}

{% set calculation = namespace(items_height=0) %}

{% set item_count = doc.items | length %}
{% set tax_count = doc.taxes | length if doc.taxes else 0 %}
{% set payment_count = doc.payments | length if doc.payments else 0 %}

{% for item in doc.items %}
    {% set item_label = item.item_name or item.item_code or '' %}
    {% set name_length = item_label | length %}

    {#
       Approximately 22 characters fit on one item-name line.
       Longer names receive additional page height.
    #}
    {% set wrapped_lines = ((name_length + 21) // 22) %}

    {% if wrapped_lines < 1 %}
        {% set wrapped_lines = 1 %}
    {% endif %}

    {#
       5mm for rate/padding
       4.5mm for every wrapped item-name line
    #}
    {% set calculation.items_height =
        calculation.items_height + 5 + (wrapped_lines * 4.5)
    %}
{% endfor %}

{#
   135mm includes:
   - Header
   - Invoice information
   - Table heading
   - Totals
   - Payments
   - Thank-you message
   - QR code
   - Cutter safety space
#}
{% set estimated_page_height =
    135
    + calculation.items_height
    + (tax_count * 5)
    + (payment_count * 5)
%}

{% if estimated_page_height < 150 %}
    {% set estimated_page_height = 150 %}
{% endif %}


<div class="pos-receipt" id="pos-receipt">

    <!-- =====================================================
         HEADER
    ====================================================== -->

    <div class="receipt-header">
        <div class="company-name">
            {{ doc.company }}
        </div>

        <div class="receipt-title">
            SALES RECEIPT
        </div>

        <div class="receipt-meta">
            <div>
                Invoice:
                <strong>{{ doc.name }}</strong>
            </div>

            <div>
                Date:

                {% if doc.posting_date and doc.posting_time %}
                    {{ frappe.utils.format_datetime(
                        doc.posting_date ~ ' ' ~ doc.posting_time,
                        "dd-MM-yyyy hh:mm a"
                    ) }}
                {% else %}
                    {{ frappe.utils.formatdate(doc.posting_date) }}
                {% endif %}
            </div>

            <div class="persian-date-row">
                Persian Date:
                <strong id="persian-date">-</strong>
            </div>
        </div>
    </div>


    <div class="divider divider-dashed"></div>


    <!-- =====================================================
         ITEMS
    ====================================================== -->

    <table class="items-table">

        <thead>
            <tr>
                <th class="text-left item-column">
                    Item
                </th>

                <th class="text-center qty-column">
                    Qty
                </th>

                <th class="text-right amount-column">
                    Amount
                </th>
            </tr>
        </thead>

        <tbody>
            {% for item in doc.items %}
                <tr class="item-row">

                    <td class="text-left">
                        <div class="item-name">
                            {{ item.item_name or item.item_code }}
                        </div>

                        {% if item.item_code and item.item_name != item.item_code %}
                            <div class="item-code">
                                {{ item.item_code }}
                            </div>
                        {% endif %}

                        <div class="item-rate">
                            @
                            {{ frappe.utils.fmt_money(
                                item.rate,
                                currency=doc.currency
                            ) }}
                        </div>
                    </td>

                    <td class="text-center value-cell">
                        {% if item.qty == item.qty | int %}
                            {{ item.qty | int }}
                        {% else %}
                            {{ item.qty }}
                        {% endif %}
                    </td>

                    <td class="text-right value-cell">
                        {{ frappe.utils.fmt_money(
                            item.amount,
                            currency=doc.currency
                        ) }}
                    </td>

                </tr>
            {% endfor %}
        </tbody>

    </table>


    <div class="divider divider-dashed"></div>


    <!-- =====================================================
         TOTALS
    ====================================================== -->

    <div class="totals-wrapper">

        <div class="total-row">
            <span>Subtotal</span>
            <span>{{ doc.get_formatted("net_total") }}</span>
        </div>


        {% if doc.discount_amount %}
            <div class="total-row">
                <span>Discount</span>

                <span>
                    - {{ doc.get_formatted("discount_amount") }}
                </span>
            </div>
        {% endif %}


        {% if doc.taxes %}
            {% for tax in doc.taxes %}
                {% if tax.tax_amount %}
                    <div class="total-row">
                        <span>
                            {{ tax.description or "Tax" }}
                        </span>

                        <span>
                            {{ tax.get_formatted("tax_amount") }}
                        </span>
                    </div>
                {% endif %}
            {% endfor %}
        {% endif %}


        <div class="divider divider-solid"></div>


        <div class="total-row grand-total-row">
            <span>TOTAL</span>
            <span>{{ doc.get_formatted("grand_total") }}</span>
        </div>


        <div class="divider divider-solid"></div>


        <!-- ================================================
             PAYMENTS
        ================================================= -->

        {% if doc.payments %}
            {% for payment in doc.payments %}
                {% if payment.amount %}
                    <div class="total-row payment-row">
                        <span>
                            {{ payment.mode_of_payment }}
                        </span>

                        <span>
                            {{ payment.get_formatted("amount") }}
                        </span>
                    </div>
                {% endif %}
            {% endfor %}
        {% endif %}


        {% if doc.change_amount %}
            <div class="total-row">
                <span>Change</span>

                <span>
                    {{ doc.get_formatted("change_amount") }}
                </span>
            </div>
        {% endif %}

    </div>


    <div class="divider divider-dashed"></div>


    <!-- =====================================================
         FOOTER
    ====================================================== -->

    <div class="receipt-footer">

        <div class="footer-message">
            Thank you for shopping with us!
        </div>

        <div class="powered-by">
            Jahan Kodak
        </div>

        <img
            id="receipt-qr-code"
            class="qr-code"
            src="https://quickchart.io/qr?text={{ doc.name }}&size=200&margin=1&format=png"
            width="96"
            height="96"
            alt="Receipt QR Code"
        >


        # <div class="cutter-space">------------------------------------------</div>
        # <div class="cutter-space">------------------------------------------</div>
        # <div class="cutter-space">------------------------------------------</div>

    </div>

</div>


{# Initial page height generated by Jinja #}
<style id="receipt-page-size">
    @page {
        size:
            80mm
            {{ estimated_page_height | round(0, "ceil") | int }}mm;
        margin: 0;
    }
</style>


<style>

    /* =====================================================
       HIDE LETTER HEAD
    ====================================================== */

    .letter-head,
    .letterhead,
    .letter-head-wrapper,
    .letterhead-wrapper,
    .print-format .letter-head,
    .print-format .letterhead {
        display: none !important;
        visibility: hidden !important;
        height: 0 !important;
        min-height: 0 !important;
        max-height: 0 !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: hidden !important;

        .print-format-header,
.print-format-header *,
.letter-head,
.letterhead,
.letter-head-wrapper,
.letterhead-wrapper {
    display: none !important;
}
    }



    /* =====================================================
       GLOBAL PRINT RESET
    ====================================================== */

    html,
    body {
        width: 80mm !important;
        min-width: 80mm !important;
        max-width: 80mm !important;

        height: auto !important;
        min-height: 0 !important;

        margin: 0 !important;
        padding: 0 !important;

        overflow: visible !important;

        background: #ffffff !important;
        color: #000000 !important;

        font-family:
            "Courier New",
            Courier,
            monospace !important;

        font-size: 12px !important;
        line-height: 1.25 !important;
    }


    /*
     * Override Frappe's normal A4 print container.
     */
    .print-format-gutter,
    .print-format {
        width: 80mm !important;
        min-width: 80mm !important;
        max-width: 80mm !important;

        height: auto !important;
        min-height: 0 !important;

        margin: 0 !important;
        padding: 0 !important;

        overflow: visible !important;

        background: #ffffff !important;
        box-shadow: none !important;
    }


    /* =====================================================
       RECEIPT CONTAINER
    ====================================================== */

    .pos-receipt {
        display: block !important;

        /*
         * Most 80mm printers have approximately
         * 72mm printable width.
         */
        width: 72mm !important;

        height: auto !important;
        min-height: 0 !important;

        margin: 0 auto !important;
        padding: 3mm 1mm 4mm 1mm !important;

        box-sizing: border-box !important;
        overflow: visible !important;

        page-break-before: avoid !important;
        page-break-after: avoid !important;
        page-break-inside: avoid !important;

        break-before: avoid-page !important;
        break-after: avoid-page !important;
        break-inside: avoid-page !important;
    }


    /* =====================================================
       HEADER
    ====================================================== */

    .receipt-header {
        display: block;
        width: 100%;
        text-align: center;
    }


    .company-name {
        margin: 0 0 2px 0 !important;
        padding: 0 !important;

        font-size: 17px !important;
        line-height: 1.15 !important;
        font-weight: 800 !important;

        text-transform: uppercase;
        letter-spacing: 0.3px;

        overflow-wrap: anywhere;
        word-break: break-word;
    }


    .receipt-title {
        margin: 0 !important;
        padding: 0 !important;

        font-size: 12px !important;
        line-height: 1.15 !important;
        font-weight: 700 !important;

        text-decoration: underline;
    }


    .receipt-meta {
        margin-top: 4px;

        font-size: 10.5px;
        line-height: 1.25;

        text-align: center;
    }


    .persian-date-row {
        font-size: 10px !important;
        line-height: 1.2 !important;
    }


    #persian-date {
        font-weight: 700 !important;
        direction: rtl !important;
        unicode-bidi: plaintext !important;
    }


    /* =====================================================
       DIVIDERS
    ====================================================== */

    .divider {
        display: block;

        width: 100%;
        height: 0;

        box-sizing: border-box;
    }


    .divider-dashed {
        margin: 6px 0;
        border-top: 1px dashed #000000;
    }


    .divider-solid {
        margin: 5px 0;
        border-top: 1.5px solid #000000;
    }


    /* =====================================================
       ITEMS TABLE
    ====================================================== */

    .items-table {
        width: 100% !important;
        max-width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;

        border: 0 !important;
        border-spacing: 0 !important;
        border-collapse: collapse !important;

        table-layout: fixed !important;
    }


    .items-table thead {
        display: table-header-group;
    }


    .items-table tbody {
        display: table-row-group;
    }


    .items-table tr {
        page-break-inside: avoid !important;
        break-inside: avoid-page !important;
    }


    .items-table th {
        margin: 0 !important;
        padding: 0 0 3px 0 !important;

        border: 0 !important;
        border-bottom: 1px solid #000000 !important;

        font-size: 10.5px !important;
        line-height: 1.2 !important;
        font-weight: 700 !important;
    }


    .items-table td {
        margin: 0 !important;
        padding: 4px 0 !important;

        border: 0 !important;

        vertical-align: top !important;

        font-size: 10.5px !important;
        line-height: 1.2 !important;

        overflow-wrap: anywhere !important;
        word-wrap: break-word !important;
        word-break: break-word !important;
    }


    .item-column {
        width: 52%;
    }


    .qty-column {
        width: 13%;
    }


    .amount-column {
        width: 35%;
    }


    .item-name {
        display: block;

        font-weight: 700;

        white-space: normal !important;
        overflow-wrap: anywhere !important;
        word-break: break-word !important;
    }


    .item-code {
        display: block;

        margin-top: 1px;

        font-size: 9px;
        line-height: 1.15;
    }


    .item-rate {
        display: block;

        margin-top: 1px;

        font-size: 9.5px;
        line-height: 1.15;
    }


    .value-cell {
        vertical-align: middle !important;
        white-space: nowrap !important;
    }


    /* =====================================================
       ALIGNMENT
    ====================================================== */

    .text-left {
        text-align: left !important;
    }


    .text-center {
        text-align: center !important;
    }


    .text-right {
        text-align: right !important;
    }


    /* =====================================================
       TOTALS
    ====================================================== */

    .totals-wrapper {
        display: block !important;
        width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;
    }


    .total-row {
        display: flex !important;

        width: 100% !important;

        justify-content: space-between !important;
        align-items: baseline !important;

        gap: 6px !important;

        margin: 0 0 3px 0 !important;
        padding: 0 !important;

        font-size: 10.5px !important;
        line-height: 1.2 !important;

        page-break-inside: avoid !important;
        break-inside: avoid-page !important;
    }


    .total-row span:first-child {
        min-width: 0;
        overflow-wrap: anywhere;
    }


    .total-row span:last-child {
        flex-shrink: 0;

        text-align: right;
        white-space: nowrap;
    }


    .grand-total-row {
        margin: 0 !important;
        padding: 1px 0 !important;

        font-size: 14px !important;
        line-height: 1.2 !important;
        font-weight: 800 !important;
    }


    /* =====================================================
       FOOTER AND QR
    ====================================================== */

    .receipt-footer {
        display: block !important;

        width: 100% !important;

        margin: 6px 0 0 0 !important;
        padding: 0 !important;

        text-align: center !important;

        page-break-inside: avoid !important;
        break-inside: avoid-page !important;
    }


    .footer-message {
        font-size: 11px;
        line-height: 1.2;
        font-weight: 700;
    }


    .powered-by {
        margin-top: 2px;
        margin-bottom: 4px;

        font-size: 9px;
        line-height: 1.2;
    }


    .qr-code {
        display: block !important;

        width: 24mm !important;
        height: 24mm !important;

        min-width: 24mm !important;
        min-height: 24mm !important;

        max-width: 24mm !important;
        max-height: 24mm !important;

        margin: 3px auto 0 auto !important;
        padding: 0 !important;

        border: 0 !important;

        object-fit: contain !important;

        page-break-before: avoid !important;
        page-break-after: avoid !important;
        page-break-inside: avoid !important;

        break-before: avoid-page !important;
        break-after: avoid-page !important;
        break-inside: avoid-page !important;
    }


    /*
     * Small space for the printer cutter.
     * Do not use 100px or 100mm here.
     */
    .cutter-space {
        display: block;
        width: 100%;
        height: 4mm;
        # padding-bottom: 40px;
        # margin-bottom: 100px
    }


    /* =====================================================
       PRINT MODE
    ====================================================== */

    @media print {

        html,
        body,
        .print-format-gutter,
        .print-format {
            width: 80mm !important;
            min-width: 80mm !important;
            max-width: 80mm !important;

            height: auto !important;
            min-height: 0 !important;

            margin: 0 !important;
            padding: 0 !important;

            overflow: visible !important;
        }


        .pos-receipt {
            page-break-before: avoid !important;
            page-break-after: avoid !important;
            page-break-inside: avoid !important;

            break-before: avoid-page !important;
            break-after: avoid-page !important;
            break-inside: avoid-page !important;
        }


        .items-table tr,
        .total-row,
        .receipt-footer,
        .qr-code {
            page-break-inside: avoid !important;
            break-inside: avoid-page !important;
        }
    }

</style>


<script>
(function () {
    "use strict";

    /* =====================================================
       GREGORIAN -> PERSIAN (JALALI) DATE
       No external library is required.
    ====================================================== */

    function gregorianToJalali(gy, gm, gd) {

        var g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
        var gy2 = (gm > 2) ? (gy + 1) : gy;

        var days = 355666 +
            (365 * gy) +
            Math.floor((gy2 + 3) / 4) -
            Math.floor((gy2 + 99) / 100) +
            Math.floor((gy2 + 399) / 400) +
            gd +
            g_d_m[gm - 1];

        var jy = -1595 + (33 * Math.floor(days / 12053));
        days = days % 12053;

        jy += 4 * Math.floor(days / 1461);
        days = days % 1461;

        if (days > 365) {
            jy += Math.floor((days - 1) / 365);
            days = (days - 1) % 365;
        }

        var jm;
        var jd;

        if (days < 186) {
            jm = 1 + Math.floor(days / 31);
            jd = 1 + (days % 31);
        } else {
            jm = 7 + Math.floor((days - 186) / 30);
            jd = 1 + ((days - 186) % 30);
        }

        return {
            year: jy,
            month: jm,
            day: jd
        };
    }


    function setPersianDate() {

        var target = document.getElementById("persian-date");

        if (!target) {
            return;
        }

        var postingDate = "{{ doc.posting_date or '' }}";

        if (!postingDate) {
            return;
        }

        var parts = postingDate.split("-");

        if (parts.length !== 3) {
            return;
        }

        var gy = parseInt(parts[0], 10);
        var gm = parseInt(parts[1], 10);
        var gd = parseInt(parts[2], 10);

        if (isNaN(gy) || isNaN(gm) || isNaN(gd)) {
            return;
        }

        var jalali = gregorianToJalali(gy, gm, gd);

        target.textContent =
            jalali.year + "/" +
            String(jalali.month).padStart(2, "0") + "/" +
            String(jalali.day).padStart(2, "0");
    }


    function setExactReceiptPageHeight() {
        var receipt = document.getElementById("pos-receipt");
        var pageStyle = document.getElementById("receipt-page-size");

        if (!receipt || !pageStyle) {
            return;
        }

        /*
         * Browsers normally calculate CSS pixels at 96 DPI.
         *
         * Convert the actual receipt height from pixels to mm
         * and add 4mm for the thermal-printer cutter.
         */
        var receiptHeightPixels = Math.ceil(
            Math.max(
                receipt.scrollHeight,
                receipt.offsetHeight,
                receipt.getBoundingClientRect().height
            )
        );

        var receiptHeightMillimetres = Math.ceil(
            (receiptHeightPixels * 25.4 / 96) + 4
        );

        /*
         * Minimum height for a very small receipt.
         */
        if (receiptHeightMillimetres < 150) {
            receiptHeightMillimetres = 150;
        }

        pageStyle.textContent =
            "@page {" +
                "size: 80mm " + receiptHeightMillimetres + "mm;" +
                "margin: 0;" +
            "}";
    }


    /*
     * Measure the receipt during all important print stages.
     */
    document.addEventListener(
        "DOMContentLoaded",
        function () {
            setPersianDate();
            setExactReceiptPageHeight();
        }
    );

    window.addEventListener(
        "load",
        function () {
            setPersianDate();
            setExactReceiptPageHeight();
        }
    );

    window.addEventListener(
        "beforeprint",
        function () {
            setPersianDate();
            setExactReceiptPageHeight();
        }
    );


    /*
     * The QR image may finish loading after the HTML.
     */
    var qrCode = document.getElementById("receipt-qr-code");

    if (qrCode) {
        qrCode.addEventListener(
            "load",
            setExactReceiptPageHeight
        );

        qrCode.addEventListener(
            "error",
            setExactReceiptPageHeight
        );
    }


    /*
     * Additional measurements for slower browsers.
     */
    setTimeout(function () {
        setPersianDate();
        setExactReceiptPageHeight();
    }, 100);

    setTimeout(function () {
        setPersianDate();
        setExactReceiptPageHeight();
    }, 300);

    setTimeout(function () {
        setPersianDate();
        setExactReceiptPageHeight();
    }, 700);

})();
</script>

/* =====================================================
   A5 PAGE
===================================================== */

@page {
    size: 148mm 210mm;
    margin: 1mm;
}


html,
body {
    margin: 0;
    padding: 0;
}


.print-format {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
}


* {
    box-sizing: border-box;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


/* =====================================================
   MAIN PAGE
===================================================== */

.azhar-page {
    width: 146mm;
    min-height: 208mm;

    margin: 0 auto;
    padding: 0;

    position: relative;

    border: 0.7px solid #b78b48;

    background: #ffffff;

    color: #111111;

    font-family: Arial, Tahoma, sans-serif;

    font-size: 7pt;

    overflow: hidden;
}


/* =====================================================
   TOP CURVE
===================================================== */

.top-curve {
    position: relative;

    width: 100%;
    height: 16mm;

    overflow: hidden;

    background: #211e1a;
}


.top-curve:after {
    content: "";

    position: absolute;

    width: 174mm;
    height: 36mm;

    left: -14mm;
    top: 4mm;

    background: #ffffff;

    border-radius: 50% 50% 0 0;

    z-index: 2;
}


.top-gold {
    position: absolute;

    width: 168mm;
    height: 34mm;

    left: -11mm;
    top: 1mm;

    background: #d5b779;

    border-radius: 50%;

    z-index: 1;
}


/* =====================================================
   HEADER
===================================================== */

.header-table {
    width: 100%;

    margin-top: -10mm;

    position: relative;

    z-index: 5;

    border-collapse: collapse;

    table-layout: fixed;
}


.header-table td {
    border: 0;

    vertical-align: top;

    padding: 0 3mm;
}


.header-left {
    width: 30%;

    padding-top: 7mm !important;

    text-align: left;

    font-size: 6.8pt;

    line-height: 1.45;
}


.header-center {
    width: 40%;

    text-align: center;

    padding-left: 0 !important;
    padding-right: 0 !important;
}


.header-right {
    width: 30%;

    padding-top: 7mm !important;

    text-align: left;

    font-size: 6.5pt;

    line-height: 1.45;
}


/* =====================================================
   LOGO
===================================================== */

.main-logo {
    display: block;

    width: 38mm;
    height: 32mm;

    margin: 0 auto;

    object-fit: contain;
}


/* =====================================================
   COMPANY NAME
===================================================== */

.company-fa {
    margin-top: -3mm;

    direction: rtl;

    color: #956927;

    font-size: 17pt;

    line-height: 1;

    font-weight: bold;
}


.company-en {
    margin-top: 1mm;

    color: #986b2b;

    font-family: Georgia, "Times New Roman", serif;

    font-size: 11.5pt;

    line-height: 1;

    font-weight: bold;
}


.company-sub {
    margin-top: 1.3mm;

    direction: rtl;

    font-size: 7.2pt;

    line-height: 1.2;
}


/* =====================================================
   CONTACTS
===================================================== */

.contact-row {
    height: 6mm;

    margin-bottom: 0.8mm;

    display: flex;

    align-items: center;

    white-space: nowrap;
}


.round-icon {
    display: inline-flex;

    width: 4.4mm;
    height: 4.4mm;

    min-width: 4.4mm;

    margin-right: 1.5mm;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #111111;

    color: #ffffff;

    font-size: 7pt;
}


.shop-address {
    margin-top: 1.2mm;

    padding-left: 1mm;

    direction: rtl;

    text-align: right;

    font-size: 6.4pt;

    line-height: 1.45;
}


.email-row {
    font-size: 5.8pt;
}


.quality-row {
    margin-top: 1.2mm;

    padding-left: 8mm;

    font-family: Georgia, "Times New Roman", serif;

    font-size: 6.8pt;

    line-height: 1.25;
}


/* =====================================================
   SALES BILL
===================================================== */

.sales-bill-wrapper {
    position: relative;

    z-index: 10;

    width: 100%;

    height: 13mm;

    margin-top: 6mm;

    display: flex;

    justify-content: center;

    align-items: center;
}


.sales-bill {
    width: 45mm;

    height: 12mm;

    padding-top: 1.3mm;

    border: 0.8px solid #b98b47;

    border-radius: 5mm;

    background: #27231e;

    text-align: center;

    box-shadow: 0 0 0 0.3px #d5b779;
}


.sales-bill-fa {
    direction: rtl;

    color: #e3bf70;

    font-size: 11pt;

    line-height: 1;

    font-weight: bold;
}


.sales-bill-en {
    margin-top: 0.8mm;

    color: #f1d99e;

    font-family: Georgia, "Times New Roman", serif;

    font-size: 6.5pt;

    line-height: 1;
}


/* =====================================================
   CUSTOMER WRAPPER
===================================================== */

.customer-wrapper {
    width: 100%;

    padding: 0 3mm;

    margin-top: -2mm;
}


/* =====================================================
   CUSTOMER BOX
===================================================== */

.customer-box {
    width: 100%;

    height: 23mm;

    border: 0.7px solid #c39955;

    border-radius: 3mm;

    border-collapse: separate;

    border-spacing: 0;

    table-layout: fixed;

    background: #ffffff;
}


.customer-box > tbody > tr > td {
    border: 0;

    vertical-align: middle;
}


.customer-side {
    width: 67%;

    padding: 2mm 3mm;
}


.invoice-side {
    width: 33%;

    padding: 1.5mm 2mm 1.5mm 1mm;
}


/* =====================================================
   CUSTOMER DATA
===================================================== */

.customer-data {
    width: 100%;

    border-collapse: collapse;

    table-layout: fixed;
}


.customer-data td {
    height: 7mm;

    padding: 0;

    border: 0;

    vertical-align: middle;

    font-size: 6.7pt;
}


.customer-label {
    width: 44%;

    white-space: nowrap;

    color: #222222;
}


.customer-value {
    width: 56%;

    padding-left: 1.5mm !important;

    border-bottom: 0.35px solid #777777 !important;

    font-size: 6.8pt;

    font-weight: bold;
}


/* =====================================================
   INVOICE INFO
===================================================== */

.invoice-data {
    width: 100%;

    border-collapse: collapse;

    table-layout: fixed;
}


.invoice-data td {
    height: 8.5mm;

    padding: 0.5mm 1mm;

    vertical-align: middle;

    border: 0;

    font-size: 6.3pt;
}


.invoice-label {
    width: 45%;

    background: #f3eee4;

    direction: rtl;

    text-align: left;

    font-weight: bold;
}


.invoice-label span {
    display: block;

    direction: ltr;

    font-size: 5.8pt;

    margin-top: 0.2mm;
}


.invoice-value {
    width: 55%;

    text-align: center;

    font-size: 6.2pt;

    border-bottom: 0.3px solid #999999 !important;
}


/* =====================================================
   ITEMS AREA
===================================================== */

.items-area {
    width: calc(100% - 6mm);

    margin: 1.2mm 3mm 0 3mm;

    position: relative;

    overflow: hidden;
}


/* =====================================================
   WATERMARK
===================================================== */

.watermark {
    position: absolute;

    z-index: 0;

    width: 65mm;

    left: 50%;
    top: 53%;

    transform: translate(-50%, -50%);

    opacity: 0.20;

    pointer-events: none;
}


.watermark img {
    display: block;

    width: 65mm;

    height: auto;
}


/* =====================================================
   ITEMS TABLE
===================================================== */

.items-table {
    position: relative;

    z-index: 2;

    width: 100%;

    border-collapse: collapse;

    table-layout: fixed;

    background: transparent;
}


.items-table th {
    height: 9mm;

    padding: 0.6mm;

    background: #27231e;

    color: #deb968;

    border: 0.55px solid #bd8b43;

    text-align: center;

    vertical-align: middle;

    direction: rtl;

    font-size: 7.2pt;

    font-weight: bold;

    line-height: 1;
}


.items-table th span {
    display: block;

    direction: ltr;

    margin-top: 0.6mm;

    color: #ffffff;

    font-size: 5.8pt;

    font-weight: normal;
}


.items-table td {
    height: 5mm;

    padding: 0.3mm 0.8mm;

    border: 0.5px solid #bd8b43;

    vertical-align: middle;

    font-size: 6.5pt;

    line-height: 1;
}


.empty-row td {
    height: 5mm;
}


/* =====================================================
   COLUMN WIDTHS
===================================================== */

.amount-col {
    width: 18%;
}


.rate-col {
    width: 18%;
}


.qty-col {
    width: 12%;
}


.item-col {
    width: 42%;
}


.number-col {
    width: 10%;
}


/* =====================================================
   ITEM CELLS
===================================================== */

.money {
    text-align: right;

    white-space: nowrap;
}


.center {
    text-align: center;
}


.item-name {
    text-align: right;

    direction: rtl;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


/* =====================================================
   BOTTOM SECTION
===================================================== */

.bottom-section {
    width: calc(100% - 10mm);

    margin: 2.5mm 5mm 0 5mm;

    display: flex;

    gap: 4mm;

    align-items: stretch;
}


/* =====================================================
   NOTES
===================================================== */

.notes-box {
    width: 58%;

    min-height: 22mm;

    padding: 1.5mm 2.5mm;

    background: #faf7ef;

    border-radius: 3mm;

    border-top: 0.6px solid #d6bd8c;

    direction: rtl;
}


.notes-title {
    color: #7c5927;

    font-size: 6.7pt;

    font-weight: bold;

    text-align: right;
}


.notes-en {
    margin-top: 0.5mm;

    direction: ltr;

    text-align: left;

    font-family: Georgia, "Times New Roman", serif;

    font-size: 5.8pt;
}


.notes-value {
    margin-top: 1mm;

    direction: ltr;

    text-align: left;

    font-size: 6.1pt;

    min-height: 9mm;
}


/* =====================================================
   RIGHT BOTTOM
===================================================== */

.bottom-right {
    width: 42%;
}


/* =====================================================
   TOTAL
===================================================== */

.total-box,
.signature-box {
    width: 100%;

    border-collapse: separate;

    border-spacing: 0;

    table-layout: fixed;

    border: 0.6px solid #c89d5c;

    border-radius: 2.5mm;

    overflow: hidden;
}


.total-box {
    height: 8mm;

    margin-bottom: 1.2mm;
}


.total-box td {
    height: 8mm;

    padding: 0.5mm 1.5mm;

    vertical-align: middle;
}


.total-title {
    width: 47%;

    background: #f5f0e7;

    direction: rtl;

    color: #6e4e22;

    font-size: 6.5pt;

    font-weight: bold;

    text-align: center;
}


.total-number {
    width: 53%;

    text-align: right;

    font-size: 8.5pt;

    font-weight: bold;

    white-space: nowrap;
}


/* =====================================================
   SIGNATURE
===================================================== */

.signature-box {
    height: 8mm;
}


.signature-box td {
    height: 8mm;

    padding: 0.5mm 1.5mm;

    vertical-align: middle;
}


.signature-title {
    width: 47%;

    background: #f5f0e7;

    direction: rtl;

    text-align: center;

    font-size: 5.9pt;
}


.signature-title span {
    display: block;

    direction: ltr;

    font-size: 5.2pt;

    margin-top: 0.2mm;
}


.signature-space {
    width: 53%;

    background: #ffffff;
}


/* =====================================================
   FOOTER
===================================================== */

.footer-design {
    width: calc(100% - 10mm);

    min-height: 19mm;

    margin: 2.2mm 5mm 1.5mm 5mm;

    padding: 1.5mm 2mm;

    display: flex;

    align-items: center;

    background: #fbf7ef;

    border-top: 0.9px solid #b98a43;

    border-bottom: 0.9px solid #b98a43;

    border-radius: 2.5mm;
}


.footer-column {
    text-align: center;
}


.return-design {
    width: 55%;

    direction: rtl;
}


.brand-message {
    width: 44%;

    direction: rtl;
}


.footer-divider {
    width: 1%;

    height: 13mm;

    border-left: 0.6px solid #cba668;
}


/* =====================================================
   FOOTER TEXT
===================================================== */

.footer-symbol {
    color: #b48743;

    font-size: 6pt;

    line-height: 1;

    margin-bottom: 0.6mm;
}


.return-title {
    color: #795725;

    font-size: 6.5pt;

    font-weight: bold;

    margin-bottom: 0.4mm;
}


.return-main {
    color: #222222;

    font-size: 6.1pt;

    font-weight: bold;

    line-height: 1.25;
}


.return-en {
    direction: ltr;

    margin-top: 0.5mm;

    color: #7f6b4b;

    font-family: Georgia, "Times New Roman", serif;

    font-size: 4.8pt;
}


.brand-message-fa {
    color: #7b5724;

    font-size: 6.4pt;

    font-weight: bold;

    line-height: 1.2;
}


.brand-message-en {
    direction: ltr;

    margin-top: 0.5mm;

    font-family: Georgia, "Times New Roman", serif;

    font-size: 5.1pt;
}


.azhar-footer-name {
    direction: ltr;

    margin-top: 0.7mm;

    color: #b68a48;

    font-family: Georgia, "Times New Roman", serif;

    font-size: 7pt;

    letter-spacing: 1.5px;

    font-weight: bold;
}


/* =====================================================
   PRINT CONTROL
===================================================== */

.items-table tr,
.bottom-section,
.footer-design {
    page-break-inside: avoid;
}


@media print {

    .azhar-page {
        width: 146mm;

        min-height: 208mm;

        margin: 0 auto;
    }

}

.print-format th {
    background-color: transparent !important;
    border-bottom: 1px solid !important;
    border-top: none !important;
}
.print-format .ql-editor {
    padding-left: 0px;
    padding-right: 0px;
}

.print-format table {
    margin-bottom: 0px;
    }
.print-format .table-data tr:last-child { 
    border-bottom: 1px solid !important;
}

.print-format .table-inner tr:last-child {
    border-bottom:none !important;
}
.print-format .table-inner {
    margin: 0px 0px;
}

.print-format .table-data ul li { 
    color:#787878 !important;
}

.no-top-border {
    border-top:none !important;
}

.table-inner td {
    padding-left: 0px !important;    
    padding-top: 1px !important;
    padding-bottom: 1px !important;
    color:#787878 !important;
}

.total {
    background-color: lightgrey !important;
    padding-top: 4px !important;
    padding-bottom: 4px !important;
}

