<div class="pos-receipt" id="pos-receipt">

    <!-- =====================================================
         HEADER
    ====================================================== -->

    <div class="receipt-header">
        <div class="company-name" dir="rtl" style="font-family: Tahoma, Arial, sans-serif;">
            جهان کودک
        </div>

        <div class="receipt-title">
            SALES RECEIPT
        </div>

        <div class="receipt-meta" style="text-align: center;">
            <div style="margin-bottom: 6px;">
                <img src="{{ get_qr_code_base64(doc.name) }}" alt="QR Code" style="margin: 4px auto; display: block; width: 100px; height: 100px;">
            </div>

            <div>
                Date:

                {% if doc.posting_date and doc.posting_time %}
                    {{ frappe.utils.format_datetime(
                        doc.posting_date ~ ' ' ~ doc.posting_time,
                        "dd-MM-yyyy hh:mm a"
                    ) }}
                {% else %}
                    {{ frappe.utils.formatdate(doc.posting_date) }}
                {% endif %}
            </div>
        </div>
    </div>


    <div class="divider divider-dashed"></div>


    <!-- =====================================================
         ITEMS
    ====================================================== -->

    <table class="items-table" dir="rtl">

        <thead>
            <tr>
                <th class="text-right item-column" style="font-family: Tahoma, Arial, sans-serif;">
                    کالا (Item)
                </th>

                <th class="text-center qty-column" style="font-family: Tahoma, Arial, sans-serif;">
                    تعداد (Qty)
                </th>

                <th class="text-left amount-column" style="font-family: Tahoma, Arial, sans-serif;">
                    مبلغ (Amount)
                </th>
            </tr>
        </thead>

        <tbody>
            {% for item in doc.items %}
                <tr class="item-row">

                    <td class="text-right">
                        <div class="item-name">
                            {{ item.item_name or item.item_code }}
                        </div>

                        {% if item.item_code and item.item_name != item.item_code %}
                            <div class="item-code">
                                {{ item.item_code }}
                            </div>
                        {% endif %}

                        <div class="item-rate">
                            @
                            {{ frappe.utils.fmt_money(
                                item.rate,
                                currency=doc.currency
                            ) }}
                        </div>
                    </td>

                    <td class="text-center value-cell">
                        {% if item.qty == item.qty | int %}
                            {{ item.qty | int }}
                        {% else %}
                            {{ item.qty }}
                        {% endif %}
                    </td>

                    <td class="text-left value-cell">
                        {{ frappe.utils.fmt_money(
                            item.amount,
                            currency=doc.currency
                        ) }}
                    </td>

                </tr>
            {% endfor %}
        </tbody>

    </table>


    <div class="divider divider-dashed"></div>


    <!-- =====================================================
         TOTALS
    ====================================================== -->

    <div class="totals-wrapper">

        <div class="total-row">
            <span>Subtotal</span>
            <span>{{ doc.get_formatted("net_total") }}</span>
        </div>


        {% if doc.discount_amount %}
            <div class="total-row">
                <span>Discount</span>

                <span>
                    - {{ doc.get_formatted("discount_amount") }}
                </span>
            </div>
        {% endif %}


        {% if doc.taxes %}
            {% for tax in doc.taxes %}
                {% if tax.tax_amount %}
                    <div class="total-row">
                        <span>
                            {{ tax.description or "Tax" }}
                        </span>

                        <span>
                            {{ frappe.utils.fmt_money(tax.tax_amount, currency=doc.currency) }}
                        </span>
                    </div>
                {% endif %}
            {% endfor %}
