                        <span>
                            {{ payment.mode_of_payment }}
                        </span>

                        <span>
                            {{ frappe.utils.fmt_money(payment.amount, currency=doc.currency) }}
                        </span>
                    </div>
                {% endif %}
            {% endfor %}
        {% endif %}


        {% if doc.change_amount %}
            <div class="total-row">
                <span>Change</span>

                <span>
                    {{ doc.get_formatted("change_amount") }}
                </span>
            </div>
        {% endif %}

    </div>


    <div class="divider divider-dashed"></div>


    <!-- =====================================================
         FOOTER
    ====================================================== -->

    <div class="receipt-footer">
        <div class="footer-message" dir="rtl" style="font-family: Tahoma, Arial, sans-serif; font-size: 10px; margin-bottom: 8px; color: black !important; font-weight: bold !important;">
